-- Create "instance" table
CREATE TABLE `instance` (`id` text NOT NULL, `auth_secret` text NOT NULL, `created_at` integer NOT NULL, PRIMARY KEY (`id`));
-- Create "workspace" table
CREATE TABLE `workspace` (`id` text NOT NULL, `name` text NOT NULL, `created_at` integer NOT NULL, `folder` text NOT NULL, PRIMARY KEY (`id`));
-- Create index "workspace_folder" to table: "workspace"
CREATE UNIQUE INDEX `workspace_folder` ON `workspace` (`folder`);
-- Create "actors" table
CREATE TABLE `actors` (`workspace_id` text NOT NULL, `id` text NOT NULL, `name` text NOT NULL, `kind` text NOT NULL, `owner_id` text NULL, `harness` text NULL, `archived` boolean NOT NULL DEFAULT FALSE, `name_confirmed` boolean NOT NULL DEFAULT FALSE, `created_at` integer NOT NULL, `auth_subject` text NULL, `model` text NULL, `effort` text NULL, `permission_mode` text NULL, `approval_policy` text NULL, `sandbox` text NULL, `invited_by` text NULL, `role` text NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `owner_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("kind" IN ('human', 'agent')), CHECK ("harness" IN ('pi', 'claude-code', 'codex')), CHECK (("kind" = 'human' AND "owner_id" IS NULL) OR ("kind" = 'agent' AND "owner_id" IS NOT NULL)), CHECK ("role" IN ('owner', 'member')), CHECK (("kind" = 'human') = ("role" IS NOT NULL)), CHECK ("archived" IN (0, 1)), CHECK ("name_confirmed" IN (0, 1)));
-- Create index "one_workspace_owner" to table: "actors"
CREATE UNIQUE INDEX `one_workspace_owner` ON `actors` (`workspace_id`) WHERE "role" = 'owner';
-- Create index "one_actor_per_subject" to table: "actors"
CREATE UNIQUE INDEX `one_actor_per_subject` ON `actors` (`workspace_id`, `auth_subject`) WHERE "auth_subject" IS NOT NULL;
-- Create "sessions" table
CREATE TABLE `sessions` (`workspace_id` text NOT NULL, `id` text NOT NULL, `actor_id` text NULL, `harness` text NOT NULL, `native_session_id` text NOT NULL, `title` text NOT NULL, `workspace` text NOT NULL, `native_locator_json` text NOT NULL, `token_hash` text NOT NULL, `status` text NOT NULL, `attention_reason` text NULL, `created_at` integer NOT NULL, `stopped_at` integer NULL, `activity` text NULL, `activity_conversation_id` text NULL, `host_id` text NULL, `pinned_at` integer NULL, `archived_at` integer NULL, `budget_cents` integer NULL, `parent_session_id` text NULL, `owner_id` text NOT NULL, `shared` text NULL, `created` boolean NOT NULL DEFAULT FALSE, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `owner_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `activity_conversation_id`) REFERENCES `conversations` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`, `actor_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `3` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("harness" IN ('pi', 'claude-code', 'codex')), CHECK ("status" IN ('connecting', 'connected', 'attention', 'stopped')), CHECK ("activity" IN ('working', 'idle')), CHECK ("shared" IN ('read', 'write')), CHECK (("status" = 'stopped') = ("stopped_at" IS NOT NULL)));
-- Create index "sessions_native_session" to table: "sessions"
CREATE UNIQUE INDEX `sessions_native_session` ON `sessions` (`workspace_id`, `harness`, `native_session_id`);
-- Create index "sessions_token_hash" to table: "sessions"
CREATE UNIQUE INDEX `sessions_token_hash` ON `sessions` (`workspace_id`, `token_hash`);
-- Create "conversations" table
CREATE TABLE `conversations` (`workspace_id` text NOT NULL, `id` text NOT NULL, `kind` text NOT NULL, `title` text NOT NULL, `paused` boolean NOT NULL DEFAULT FALSE, `next_seq` integer NOT NULL DEFAULT 1, `created_at` integer NOT NULL, `parent_id` text NULL, `root_message_id` text NULL, `closed_at` integer NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `root_message_id`) REFERENCES `messages` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `parent_id`) REFERENCES `conversations` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("kind" IN ('dm', 'group', 'thread')), CHECK (("kind" = 'thread') = ("parent_id" IS NOT NULL AND "root_message_id" IS NOT NULL)), CHECK ("paused" IN (0, 1)));
-- Create index "one_open_thread_per_root" to table: "conversations"
CREATE UNIQUE INDEX `one_open_thread_per_root` ON `conversations` (`workspace_id`, `root_message_id`) WHERE "closed_at" IS NULL;
-- Create "conversation_members" table
CREATE TABLE `conversation_members` (`workspace_id` text NOT NULL, `conversation_id` text NOT NULL, `actor_id` text NOT NULL, `session_id` text NULL, PRIMARY KEY (`workspace_id`, `conversation_id`, `actor_id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `actor_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`, `conversation_id`) REFERENCES `conversations` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `3` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "conversation_members_session" to table: "conversation_members"
CREATE INDEX `conversation_members_session` ON `conversation_members` (`workspace_id`, `session_id`);
-- Create "messages" table
CREATE TABLE `messages` (`workspace_id` text NOT NULL, `id` text NOT NULL, `conversation_id` text NOT NULL, `seq` integer NOT NULL, `author_id` text NOT NULL, `text` text NOT NULL, `reply_to_delivery_id` text NULL, `created_at` integer NOT NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `reply_to_delivery_id`) REFERENCES `deliveries` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `author_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`, `conversation_id`) REFERENCES `conversations` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `3` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "messages_workspace_id_conversation_id_seq" to table: "messages"
CREATE UNIQUE INDEX `messages_workspace_id_conversation_id_seq` ON `messages` (`workspace_id`, `conversation_id`, `seq`);
-- Create index "messages_workspace_id_reply_to_delivery_id" to table: "messages"
CREATE UNIQUE INDEX `messages_workspace_id_reply_to_delivery_id` ON `messages` (`workspace_id`, `reply_to_delivery_id`);
-- Create "deliveries" table
CREATE TABLE `deliveries` (`workspace_id` text NOT NULL, `id` text NOT NULL, `message_id` text NOT NULL, `actor_id` text NOT NULL, `session_id` text NOT NULL, `status` text NOT NULL, `native_request_id` text NULL, `last_error` text NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `actor_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`, `message_id`) REFERENCES `messages` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `3` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("status" IN ('stored', 'uncertain', 'notified', 'read')));
-- Create index "deliveries_workspace_id_message_id_actor_id" to table: "deliveries"
CREATE UNIQUE INDEX `deliveries_workspace_id_message_id_actor_id` ON `deliveries` (`workspace_id`, `message_id`, `actor_id`);
-- Create index "deliveries_session" to table: "deliveries"
CREATE INDEX `deliveries_session` ON `deliveries` (`workspace_id`, `session_id`, `status`, `created_at`);
-- Create "chat_outbox" table
CREATE TABLE `chat_outbox` (`workspace_id` text NOT NULL, `event_id` text NOT NULL, `payload_json` text NOT NULL, `recipient_actor_ids_json` text NOT NULL, `created_at` integer NOT NULL, `published_at` integer NULL, PRIMARY KEY (`workspace_id`, `event_id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "chat_outbox_pending" to table: "chat_outbox"
CREATE INDEX `chat_outbox_pending` ON `chat_outbox` (`workspace_id`, `created_at`) WHERE "published_at" IS NULL;
-- Create "tool_approvals" table
CREATE TABLE `tool_approvals` (`workspace_id` text NOT NULL, `id` text NOT NULL, `session_id` text NOT NULL, `delivery_id` text NULL, `native_request_id` text NOT NULL, `kind` text NOT NULL DEFAULT 'permission', `summary` text NOT NULL, `details_json` text NOT NULL, `status` text NOT NULL, `decision` text NULL, `scope` text NULL, `reason` text NULL, `answer_json` text NULL, `last_error` text NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL, `decision_delivered_at` integer NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `delivery_id`) REFERENCES `deliveries` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("status" IN ('pending', 'decided', 'uncertain', 'delivered', 'resolved')), CHECK ("kind" IN ('permission', 'question', 'form')), CHECK ("decision" IN ('allow', 'deny')), CHECK ("scope" IN ('once', 'session', 'always')), CHECK (("kind" = 'permission' AND "answer_json" IS NULL) OR ("kind" <> 'permission' AND "decision" IS NULL)), CHECK ("status" NOT IN ('decided', 'uncertain', 'delivered') OR "decision" IS NOT NULL OR "answer_json" IS NOT NULL));
-- Create index "tool_approvals_workspace_id_session_id_native_request_id" to table: "tool_approvals"
CREATE UNIQUE INDEX `tool_approvals_workspace_id_session_id_native_request_id` ON `tool_approvals` (`workspace_id`, `session_id`, `native_request_id`);
-- Create "schedules" table
CREATE TABLE `schedules` (`workspace_id` text NOT NULL, `id` text NOT NULL, `session_id` text NOT NULL, `cron` text NOT NULL, `prompt` text NOT NULL, `enabled` boolean NOT NULL, `next_run_at` integer NULL, `last_run_at` integer NULL, `last_error` text NULL, `created_at` integer NOT NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "schedules_due" to table: "schedules"
CREATE INDEX `schedules_due` ON `schedules` (`workspace_id`, `next_run_at`) WHERE "enabled" = TRUE;
-- Create "invites" table
CREATE TABLE `invites` (`workspace_id` text NOT NULL, `id` text NOT NULL, `token_hash` text NOT NULL, `created_by` text NOT NULL, `created_at` integer NOT NULL, `expires_at` integer NOT NULL, `accepted_by` text NULL, `accepted_at` integer NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `accepted_by`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`, `created_by`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "invites_workspace_id_token_hash" to table: "invites"
CREATE UNIQUE INDEX `invites_workspace_id_token_hash` ON `invites` (`workspace_id`, `token_hash`);
-- Create "triggers" table
CREATE TABLE `triggers` (`workspace_id` text NOT NULL, `id` text NOT NULL, `session_id` text NOT NULL, `event` text NOT NULL, `failures_only` boolean NOT NULL, `prompt` text NOT NULL, `enabled` boolean NOT NULL, `last_seen` text NULL, `last_run_at` integer NULL, `last_error` text NULL, `created_at` integer NOT NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("event" IN ('ci')));
-- Create "hosts" table
CREATE TABLE `hosts` (`workspace_id` text NOT NULL, `id` text NOT NULL, `name` text NOT NULL, `person_id` text NOT NULL, `open` boolean NOT NULL, `created_at` integer NOT NULL, `seen_at` integer NOT NULL, `secret_hash` text NULL, `link_hash` text NULL, `link_expires_at` integer NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `person_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "hosts_workspace_id_secret_hash" to table: "hosts"
CREATE UNIQUE INDEX `hosts_workspace_id_secret_hash` ON `hosts` (`workspace_id`, `secret_hash`);
-- Create index "hosts_workspace_id_link_hash" to table: "hosts"
CREATE UNIQUE INDEX `hosts_workspace_id_link_hash` ON `hosts` (`workspace_id`, `link_hash`);
-- Create "extensions" table
CREATE TABLE `extensions` (`workspace_id` text NOT NULL, `id` text NOT NULL, `version` text NOT NULL, `source` text NOT NULL, `dev` boolean NOT NULL, `enabled` boolean NOT NULL, `error` text NULL, `manifest_json` text NOT NULL, `contributes_json` text NULL, `installed_at` integer NOT NULL, `updated_at` integer NOT NULL, `proposed_by` text NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create "extension_values" table
CREATE TABLE `extension_values` (`workspace_id` text NOT NULL, `extension_id` text NOT NULL, `kind` text NOT NULL, `key` text NOT NULL, `value_json` text NOT NULL, `updated_at` integer NOT NULL, PRIMARY KEY (`workspace_id`, `extension_id`, `kind`, `key`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `extension_id`) REFERENCES `extensions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("kind" IN ('setting', 'secret', 'value')));
-- Create "extension_calls" table
CREATE TABLE `extension_calls` (`workspace_id` text NOT NULL, `id` text NOT NULL, `extension_id` text NOT NULL, `action` text NOT NULL, `actor_id` text NULL, `session_id` text NULL, `by` text NULL, `at` integer NOT NULL, `duration_ms` integer NOT NULL, `ok` boolean NOT NULL, `error` text NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "extension_calls_by_extension" to table: "extension_calls"
CREATE INDEX `extension_calls_by_extension` ON `extension_calls` (`workspace_id`, `extension_id`, `at`);
-- Create "background_commands" table
CREATE TABLE `background_commands` (`workspace_id` text NOT NULL, `id` text NOT NULL, `session_id` text NOT NULL, `command` text NOT NULL, `folder` text NOT NULL, `status` text NOT NULL, `pid` integer NULL, `exit_code` integer NULL, `started_at` integer NOT NULL, `ended_at` integer NULL, `told_at` integer NULL, `error` text NULL, PRIMARY KEY (`workspace_id`, `id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `session_id`) REFERENCES `sessions` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("status" IN ('running', 'exited', 'stopped', 'lost')));
-- Create index "background_commands_by_session" to table: "background_commands"
CREATE INDEX `background_commands_by_session` ON `background_commands` (`workspace_id`, `session_id`, `started_at`);
-- Create "read_positions" table
CREATE TABLE `read_positions` (`workspace_id` text NOT NULL, `actor_id` text NOT NULL, `kind` text NOT NULL, `subject_id` text NOT NULL, `position` integer NOT NULL, `updated_at` integer NOT NULL, PRIMARY KEY (`workspace_id`, `actor_id`, `kind`, `subject_id`), CONSTRAINT `0` FOREIGN KEY (`workspace_id`, `actor_id`) REFERENCES `actors` (`workspace_id`, `id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK ("kind" IN ('conversation', 'session')), CHECK ("position" >= 0));
